import { Flow, wfa, action, trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['sla_flow'],
        name: 'SLA Task Flow',
        description: 'SLA trigger with reference column dot-walking',
    },
    wfa.trigger(trigger.application.slaTask, { $id: Now.ID['sla_trigger'] }, {}),
    (params) => {
        // Test dot-walking on task_sla_record reference column
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_sla_record_details'] },
            {
                log_level: 'info',
                log_message: `SLA Record - Mod Count: ${wfa.dataPill(params.trigger.task_sla_record.sys_mod_count, 'integer')}, Active: ${wfa.dataPill(params.trigger.task_sla_record.active, 'boolean')}, is_repair: ${wfa.dataPill(params.trigger.sla_flow_inputs.is_repair, 'boolean')}`,
            }
        )

        // Test basic trigger output
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_sla_basic'] },
            {
                log_level: 'warn',
                log_message: 'SLA task triggered successfully',
            }
        )
    }
)
